<?php
declare(strict_types=1);
namespace Tests\Integration\Infrastructure;
use App\Domain\Generations\Generation;use App\Domain\Generations\GenerationId;use App\Infrastructure\Persistence\PDO\PdoGenerationRepository;use PDO;use PHPUnit\Framework\TestCase;
final class PdoGenerationRepositoryTest extends TestCase { public function testCrudRoundTrip(): void { $pdo=new PDO('sqlite::memory:'); $pdo->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION); $pdo->exec('CREATE TABLE generations (id TEXT PRIMARY KEY,user_id TEXT,subject TEXT,topic TEXT,details TEXT,grade TEXT,duration INTEGER,lang TEXT,prompt TEXT,status TEXT,result_md TEXT,result_json TEXT,created_at TEXT,updated_at TEXT)'); $repo=new PdoGenerationRepository($pdo); $g=Generation::create(GenerationId::fromString('gen-1'),'u-1','Math','Fractions','detail','5',45,'ru','prompt'); $repo->save($g); $loaded=$repo->byId(GenerationId::fromString('gen-1')); self::assertNotNull($loaded); self::assertSame('Math',$loaded->subject()); $g->update('done','# md','{}'); $repo->save($g); self::assertSame('done',$repo->byId(GenerationId::fromString('gen-1'))?->status()); $repo->delete(GenerationId::fromString('gen-1')); self::assertNull($repo->byId(GenerationId::fromString('gen-1'))); }}
